import{_ as e,o as a,c as d,a2 as s}from"./chunks/framework.Bg-Zxr5O.js";const v=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/Invoking-pspp_002ddump_002dsav.md","filePath":"manual-zh/Invoking-pspp_002ddump_002dsav.md","lastUpdated":1785684581000}'),o={name:"manual-zh/Invoking-pspp_002ddump_002dsav.md"};function c(t,p,n,m,_,r){return a(),d("div",null,[...p[0]||(p[0]=[s(`<h2 id="_20-调用-pspp-dump-sav" tabindex="-1">20 调用 <code>pspp-dump-sav</code> <a class="header-anchor" href="#_20-调用-pspp-dump-sav" aria-label="Permalink to &quot;20 调用 \`pspp-dump-sav\`&quot;">​</a></h2><p><code>pspp-dump-sav</code> 是 PSPP 附带的命令行实用程序。默认情况下它未安装，因此在您的 PSPP 安装中可能缺少它。它读取一个或多个 SPSS 系统文件并打印其内容。该输出格式对于调试系统文件读取器和写入器，以及发现如何解释未知或了解不多的记录很有用。最终用户可能会发现该输出有助于向 PSPP 开发人员提供 PSPP 未能准确读取的系统文件的信息。</p><p>概要：</p><pre><code>pspp-dump-sav [-d[maxcases] | --data[=maxcases]] file…

pspp-dump-sav --help | -h

pspp-dump-sav --version | -v
</code></pre><p>以下选项被接受：</p><p><code>-d</code>[maxcases] <code>--data</code>[<code>=</code>maxcases]</p><p>默认情况下，<code>pspp-dump-sav</code> 不打印系统文件中的任何数据，只打印文件头。指定此选项以同时打印数据。如果指定了 maxcases，则它限制打印的个案数量。</p><p><code>-h</code><code>--help</code></p><p>在 stdout 上打印用法消息并退出。</p><p><code>-v</code><code>--version</code></p><p>在 stdout 上打印版本信息并退出。</p><p>某些阻止文件成功解释的错误会导致 <code>pspp-dump-sav</code> 退出，而不读取命令行上给出的任何其他文件。</p>`,12)])])}const i=e(o,[["render",c]]);export{v as __pageData,i as default};
